(()=>{'use strict';function init(){const byId=id=>document.getElementById(id);const button=byId('studio-live-share'),link=byId('studio-live-whatsapp-link'),status=byId('studio-live-share-status');if(!button)return;button.addEventListener('click',()=>{link.hidden=true;const raw=byId('studio-live-url').value.trim(),title=byId('studio-live-title').value.trim()||'Our live programme',mode=byId('studio-live-mode').value;if(!byId('studio-live-confirm').checked){status.textContent='Verify the public broadcast before sharing it as live.';return;}let url;try{url=new URL(raw);}catch{status.textContent='Enter a valid public HTTPS viewing link.';return;}if(url.protocol!=='https:'||url.username||url.password||!url.hostname.includes('.')||/^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(url.hostname)){status.textContent='Use a publicly accessible HTTPS viewing URL, not a local address.';return;}const message='Join our '+(mode==='podcast'?'live podcast':'livestream')+': '+title+'\nWatch here: '+url.href;link.href='https://api.whatsapp.com/send?text='+encodeURIComponent(message);link.hidden=false;status.textContent='WhatsApp invitation ready. You must open WhatsApp and send it yourself.';});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();